// HTTP security headers for every response of the website (used in hooks.server.ts).
// The Content-Security-Policy itself is generated by SvelteKit (csp in vite.config.ts, with a
// nonce for its own inline script); only the image host from ASSETS_BASE_URL is added here,
// because it is known at run time, not at build time.

export const SECURITY_HEADERS: Readonly<Record<string, string>> = {
	// Don't guess file types (e.g. treat an upload as a script)
	'x-content-type-options': 'nosniff',
	// Other sites only see our origin, never the full URL
	'referrer-policy': 'strict-origin-when-cross-origin',
	// No embedding in frames on other sites (clickjacking); CSP frame-ancestors does the same
	// for current browsers
	'x-frame-options': 'DENY',
	// Browser features the website never uses stay switched off
	'permissions-policy': 'camera=(), microphone=(), geolocation=(), payment=(), usb=()',
	// Pages opened from here can't control this window (window.opener)
	'cross-origin-opener-policy': 'same-origin'
};

/** Adds `source` to one directive of a CSP header value (once), keeping everything else */
export function addCspSource(policy: string, directive: string, source: string): string {
	let found = false;
	const parts = policy
		.split(';')
		.map((part) => part.trim())
		.filter(Boolean)
		.map((part) => {
			const [name, ...values] = part.split(/\s+/);
			if (name !== directive) return part;
			found = true;
			return values.includes(source) ? part : [name, ...values, source].join(' ');
		});
	if (!found) parts.push(`${directive} ${source}`);
	return parts.join('; ');
}

/** Origin (scheme + host + port) of a URL, or null when it isn't a valid http(s) URL */
export function originOf(url: string): string | null {
	try {
		const { origin, protocol } = new URL(url);
		return protocol === 'http:' || protocol === 'https:' ? origin : null;
	} catch {
		return null;
	}
}

export function applySecurityHeaders(
	headers: Headers,
	{ assetsOrigin, https }: { assetsOrigin: string | null; https: boolean }
) {
	for (const [name, value] of Object.entries(SECURITY_HEADERS)) {
		if (!headers.has(name)) headers.set(name, value);
	}
	// Only over HTTPS (browsers ignore it on plain HTTP); the proxy in front may set it too
	if (https && !headers.has('strict-transport-security')) {
		headers.set('strict-transport-security', 'max-age=31536000; includeSubDomains');
	}
	const csp = headers.get('content-security-policy');
	if (csp && assetsOrigin) {
		headers.set('content-security-policy', addCspSource(csp, 'img-src', assetsOrigin));
	}
}
